const fs = require('fs');
const { filterFarmsForSchedule } = require('/data/shared/rotem/lib/compare-anomaly.js');

const manual =
  (typeof $execution !== 'undefined' && ['manual', 'test', 'cli'].includes($execution.mode)) ||
  ($('Manual Test Trigger').isExecuted === true);

const config = JSON.parse(fs.readFileSync('/data/shared/rotem/farms.json', 'utf8'));
const thresholds = JSON.parse(fs.readFileSync('/data/shared/rotem/thresholds.json', 'utf8'));

const farms = (config.farms || []).filter((farm) => {
  if (manual) return true;
  return filterFarmsForSchedule([farm], farm.timezone);
});

if (farms.length === 0) {
  return [{ json: { skipped: true, reason: manual ? 'no_farms_configured' : 'no_farms_due_this_hour' } }];
}

return farms.map((farm) => ({
  json: {
    farm,
    config,
    thresholds,
    manual,
    skipScheduleCheck: manual,
    skipped: false,
  },
}));

const fs = require('fs');
const ROTEM_ROOT = '/data/shared/rotem';

// Task runner caches require() — bust cache so volume-mounted lib updates apply.
for (const mod of [`${ROTEM_ROOT}/lib/orchestrator.js`, `${ROTEM_ROOT}/lib/rotem-client.js`]) {
  try {
    delete require.cache[require.resolve(mod)];
  } catch {}
}

const { processFarm } = require(`${ROTEM_ROOT}/lib/orchestrator.js`);
const source = $json;

// Always load credentials from disk; do not trust farm object passed through n8n items.
const config = JSON.parse(fs.readFileSync(`${ROTEM_ROOT}/farms.json`, 'utf8'));
const thresholds = JSON.parse(fs.readFileSync(`${ROTEM_ROOT}/thresholds.json`, 'utf8'));
const farm = (config.farms || []).find((f) => f.id === source.farm?.id);

if (!farm) {
  return {
    json: {
      skipped: false,
      error: true,
      farmId: source.farm?.id,
      farmName: source.farm?.displayName || source.farm?.id,
      message: `Farm not found in farms.json: ${source.farm?.id}`,
      config,
    },
  };
}

if (!farm.rotemUsername || !farm.rotemPassword) {
  return {
    json: {
      skipped: false,
      error: true,
      farmId: farm.id,
      farmName: farm.displayName || farm.id,
      message: 'Missing rotemUsername or rotemPassword in farms.json',
      config,
    },
  };
}

try {
  const result = await processFarm(farm, config, thresholds, {
    skipScheduleCheck: source.skipScheduleCheck || source.manual,
  });

  if (result.skipped) {
    return {
      json: {
        skipped: true,
        reason: result.reason,
        farmId: result.farmId,
        config,
        error: false,
      },
    };
  }

  return {
    json: {
      ...result,
      config,
      error: false,
      skipped: false,
    },
  };
} catch (error) {
  return {
    json: {
      skipped: false,
      error: true,
      farmId: farm.id,
      farmName: farm.displayName || farm.id,
      message: error.message,
      config,
    },
  };
}

const fs = require('fs');
const path = require('path');

const item = $input.item.json;
const email = item.email;
if (!email) throw new Error('Missing email payload');

const outbox = '/data/shared/rotem/outbox';
fs.mkdirSync(outbox, { recursive: true });
const slug = `${item.farmId}-${Date.now()}`;
const htmlPath = path.join(outbox, `${slug}.html`);
const metaPath = path.join(outbox, `${slug}.meta.json`);

fs.writeFileSync(htmlPath, email.html);
fs.writeFileSync(path.join(outbox, `${slug}.txt`), email.text);
fs.writeFileSync(
  metaPath,
  JSON.stringify(
    {
      to: email.to,
      from: email.from,
      subject: email.subject,
      farmId: item.farmId,
      alertCount: item.report?.alertCount ?? 0,
      savedAt: new Date().toISOString(),
    },
    null,
    2,
  ),
);

return {
  json: {
    ...item,
    outboxPath: htmlPath,
    outboxMetaPath: metaPath,
  },
};

const item = $input.item.json;
const config = item.config || {};
const to = config.recipientEmail || 'you@example.com';
const from = config.senderEmail || to;
const farmLabel = item.farmName || item.farmId || 'unknown farm';

return {
